prop circles_cut_one_another(o, p cart(R, R), radius, other_radius R+):
    m0::f0::circle(o, radius) != m0::f0::circle(p, other_radius)
    exist a, b cart(R, R) st {a != b, $m0::f0::is_on_circle(a, o, radius), $m0::f0::is_on_circle(a, p, other_radius), $m0::f0::is_on_circle(b, o, radius), $m0::f0::is_on_circle(b, p, other_radius)}

