prop is_circular_arc_with_chord(arc power_set(cart(R, R)), a, b cart(R, R)):
    a != b
    exist o cart(R, R), radius R+, side R st {$m0::f0::is_on_circle(a, o, radius), $m0::f0::is_on_circle(b, o, radius), side = 1 or side = -1, arc = f11::chosen_circle_arc(o, a, b, radius, side)}
